window.CONTENT_PARTS = window.CONTENT_PARTS || [];
window.CONTENT_PARTS.push({ lang: "en", units: [

/* ===================== START HERE ===================== */

{ id: "en-steps", group: "Start here", order: 10,
  title: "Six steps to a great story",
  intro: "Every good composition is built in the same six steps. Learn them once and you can use them for any topic, any picture and any year.",
  blocks: [
    { type: "text", html: "Writing a story is a bit like cooking a meal. If you throw everything into the pot at once, it turns into a mess. If you follow the steps, it comes out delicious. Here are the six steps good writers follow, every single time." },
    { type: "steps", items: [
      { title: "Read the question", text: "Read the title and the instructions twice. Underline the key words. Ask yourself: what MUST happen in my story? If there are pictures, check what kind they are: a picture series tells one story in order, so use every picture; picture ideas are suggestions, so choose at least one that gives you a strong story. A beautiful story that does not answer the question will not score well." },
      { title: "Plan your story", text: "Spend about ten minutes on a story mountain: beginning, build-up, problem and climax, solution, ending. Write short notes, not full sentences. Decide your main character, the setting, the problem and the lesson before you write a single paragraph." },
      { title: "Start strong", text: "Hook the reader in the first sentence with a sound, some speech, an action, a question or a vivid setting. Avoid “One day…” and avoid starting with waking up and brushing your teeth. Jump in close to the action." },
      { title: "Show the feelings", text: "Do not just say “I was scared”. Show it with the body, actions and the five senses: “My legs would not move, and my hands were cold and damp.” Slow down at the most exciting part and spend the most words there." },
      { title: "End with meaning", text: "Tell the reader what changed. What did your character learn, feel or decide? Link back to the title so the reader knows the story answered the question. Never end with “Then I woke up. It was all a dream.”" },
      { title: "Check your work", text: "Leave five minutes at the end. Read your story quietly in your head as if you were reading it aloud. Fix spelling, capital letters, full stops, tenses and speech marks. Make sure every paragraph makes sense." }
    ] },
    { type: "tip", html: "<b>Timing tip:</b> If you have about 50 minutes for a composition, try this plan: <b>about 10 minutes</b> to read the question and plan, <b>about 35 minutes</b> to write, and <b>about 5 minutes</b> to check. It feels slow to plan, but a good plan makes the writing much faster. Wear a watch and glance at it when you finish your opening and again when you reach the climax." },
    { type: "tip", html: "<b>Practise the clock:</b> At home, set a timer for ten minutes and plan a story only. Do this a few times and planning will start to feel quick and easy." },
    { type: "cards", title: "What markers look for", items: [
      { tag: "Content", title: "Does your story answer the question?", text: "The story must be about the topic and, if there are pictures, use at least one of them clearly. The main event should be linked to the title, not just mentioned at the end.", ex: "Topic: “A Kind Act”. The kind act should be the heart of the story, not one line in the last paragraph." },
      { tag: "Content", title: "Is the story well developed?", text: "Markers look for a clear beginning, a problem that builds up, an exciting climax, a believable solution and a meaningful ending. The climax should get the most detail.", ex: "Good: two rich paragraphs about the moment the wallet is found and the choice to return it." },
      { tag: "Content", title: "Is it interesting and believable?", text: "Characters should act like real people. Feelings should be shown, not just named. Small, true-to-life details make the story come alive.", ex: "Instead of a superhero rescue, a child who calls for help and stays calm feels real." },
      { tag: "Language", title: "Is the language accurate?", text: "Correct grammar, spelling and punctuation. The tense stays in the past. Sentences begin with capital letters and end with full stops.", ex: "“I runned to the gate” becomes “I ran to the gate.”" },
      { tag: "Language", title: "Is the vocabulary rich and precise?", text: "Strong verbs, precise adjectives and well-chosen phrases, used correctly. One perfect word is better than three fancy ones used wrongly.", ex: "“walked slowly” becomes “trudged”." },
      { tag: "Language", title: "Are the sentences varied and well organised?", text: "A mix of short and long sentences, different sentence starters, clear paragraphs and smooth linking words such as “Moments later” and “As a result”.", ex: "Trembling, I reached for the handle. It was locked." }
    ] },
    { type: "text", title: "How to use this site", html: "Each lesson has two parts. First, <b>learn</b>: read the cards, tips and examples. Then, <b>practise</b>: try the questions at the bottom. Every time you answer a question or reveal a model answer, you earn a <b>star</b>. Do not rush to reveal the answer. Try your own version first, then compare. You will learn the most from the gap between your answer and the model." },
    { type: "text", html: "A good order to follow: work through <b>Start here</b> first, then <b>Building blocks</b> (openings, endings, paragraphs, sentences, dialogue and grammar). After that, explore the <b>Word banks</b> and <b>Techniques</b>, read the <b>Model essays</b>, and finally write your own stories in <b>Practice</b>." },
    { type: "tip", html: "<b>Little and often:</b> Fifteen minutes a day beats two hours once a week. Try one lesson, collect your stars, and use one new idea in your next piece of writing." }
  ] },

{ id: "en-question", group: "Start here", order: 11,
  title: "Understand the question",
  intro: "Before you write a single word, make sure you know exactly what the question wants. A wonderful story that misses the topic cannot score well.",
  blocks: [
    { type: "cards", title: "Two kinds of questions", items: [
      { tag: "Type 1", title: "Topic-based questions", text: "You are given a title or a topic, sometimes with a few helping words or pictures. Your whole story must be about that topic.", ex: "Write a composition of at least 150 words about a time you helped someone in need." },
      { tag: "Type 2", title: "Picture-based questions", text: "You are given some pictures, and there are two kinds. A <b>picture series</b> (common in lower and middle primary) shows ONE story in order, often with helping words: use every picture, in order, and explain what happens between them. <b>Picture ideas</b> (common in upper primary and the PSLE) come with a topic: the pictures are suggestions, and you must use at least one of them as an important part of your story. Always follow the instructions on your own paper.", ex: "Picture 1: a boy at a hawker centre. Picture 2: a wallet under a table. Picture 3: the boy talking to an old man." }
    ] },
    { type: "cards", title: "Reading the question carefully", items: [
      { tag: "Key words", title: "Underline the key words", text: "Find the words that tell you WHAT must happen and WHO it must happen to. Small words matter: “a mistake” is different from “a mistake you made”.", ex: "Write about a time you <b>made a mistake</b> and <b>what you learnt</b> from it.<br>You must: make the mistake yourself, AND show the lesson." },
      { tag: "Theme vs plot", title: "The theme is the big idea", text: "The theme is the big idea of the topic, such as honesty, courage or kindness. The plot is the actual events. Many different plots can fit one theme. Choose the plot you can write about most vividly.", ex: "Theme: honesty.<br>Plot A: returning a lost wallet at a hawker centre.<br>Plot B: owning up to breaking Grandma’s vase." },
      { tag: "Pictures", title: "Use at least one picture", text: "If pictures are given, use at least one of them clearly in your story. The picture should play an important part, not just appear in passing. Mention it in your plan so you do not forget.", ex: "Picture of an umbrella: the umbrella could be lent to a stranger in a storm, which is the kind act at the centre of the story." },
      { tag: "Relevance", title: "Stay on the topic", text: "Every paragraph should help to tell THIS story. Long descriptions of breakfast, the journey to school or what you did after dinner waste words and can pull the story off topic.", ex: "Topic: “Lost”. Spend your words on being lost and found, not on the shopping list." },
      { tag: "Main character", title: "Check whose story it is", text: "Some questions ask about “you”, so write in the first person (I, me, my). Others let you write about anyone. Read the instructions to see which is wanted.", ex: "“Write about a time you were brave” means YOU must be the brave one." },
      { tag: "Twist", title: "Think beyond the first idea", text: "The first idea that pops into your head is often the same idea everyone else has. Spend thirty seconds thinking of a second and third idea, then pick the one with the most feeling.", ex: "Topic: “A Surprise”. First idea: a birthday party. Better idea: Grandpa, who never cooks, makes you a terrible but wonderful birthday breakfast." }
    ] },
    { type: "tip", html: "<b>The one-sentence test:</b> Before you write, finish this sentence: “My story is about ___, and it answers the question because ___.” If you cannot finish it, your plot does not fit yet." },
    { type: "mcq", title: "Which plot fits?", intro: "Read the topic and choose the plot that fits it best.", items: [
      { q: "Which plot best fits the topic “A Kind Act”?", o: ["Wei Ming wins first prize in a drawing competition.", "Wei Ming carries an elderly neighbour’s heavy groceries up to her flat when the lift breaks down.", "Wei Ming goes to the zoo with his class and sees a white tiger."], a: 1, e: "Only this plot has someone doing something kind for another person. The other two are about winning and sightseeing." },
      { q: "Topic: “A Time I Made a Mistake”. Which plot fits best?", o: ["My friend broke the class fan and blamed the wind.", "I forgot to lock the gate and our dog ran out onto the road. I had to find him and learnt to be more careful.", "We had a fun picnic at East Coast Park."], a: 1, e: "The topic says “I” made the mistake. The first plot is someone else’s mistake, and the picnic has no mistake at all." },
      { q: "Topic: “An Unforgettable Day”. Which plot will make the most interesting story?", o: ["I went to school, had lessons, ate lunch and went home.", "Our class went to the Science Centre and it was fun.", "During a class trip, my friend fainted in the heat and I had to stay calm and get help."], a: 2, e: "A strong story needs a problem. Only the third plot has a problem and a moment of tension that makes the day unforgettable." },
      { q: "The pictures show: a ball, a broken window, a boy talking to an old lady. Which plot uses the pictures best?", o: ["Jun Hao kicks his ball through Mrs Lim’s window, hides, then decides to knock on her door and apologise.", "Jun Hao plays football and scores a goal.", "Jun Hao visits his grandmother and they bake cookies."], a: 0, e: "This plot uses all three pictures and links them together into one story with a problem and a solution." },
      { q: "Topic: “Lost”. Which plan stays most relevant?", o: ["Two paragraphs on breakfast, one on the bus ride, one sentence on getting lost.", "One short paragraph to set the scene, then most of the story about being lost in a crowded mall and how I was found.", "A story about losing a game of chess."], a: 1, e: "The topic is about being lost, so most of the words should be spent there. The chess plot uses a different meaning of “lost”, which is risky unless the question allows it." },
      { q: "What is the THEME of a story about returning a wallet full of money?", o: ["Hawker centres", "Honesty", "Money"], a: 1, e: "The theme is the big idea or value. The wallet and the hawker centre are part of the plot and setting." },
      { q: "Topic: “A Brave Act”. Which is the strongest way to show bravery?", o: ["I was very brave.", "I was brave because I am a brave person.", "My knees were shaking, but I stepped forward and told the teacher who had really taken the money."], a: 2, e: "Real bravery is doing the right thing even when you are scared. Showing the fear makes the bravery believable." },
      { q: "Upper primary: you are given a topic and three pictures as ideas. What is the minimum you must do?", o: ["Use at least one picture clearly in the story.", "Describe every picture in detail at the start.", "Ignore the pictures and write any story."], a: 0, e: "When pictures are ideas, use at least one and make it an important part of the story. You may use more if they help. (In a picture series that tells one story in order, you use them all.)" }
    ] },
    { type: "avoid", items: [
      "Writing a story you memorised that does not really fit the topic.",
      "Mentioning the topic only in the last sentence: “And that was my kind act.”",
      "Using a picture for one line and then forgetting it.",
      "Spending half the story on waking up, breakfast and travelling.",
      "Writing about “my friend” when the question asks about YOU."
    ], note: "Markers check first whether the story answers the question. Keep the topic at the centre of every paragraph." }
  ] },

{ id: "en-plan", group: "Start here", order: 12,
  title: "Plan with a story mountain",
  intro: "Every good story climbs up to an exciting problem, then comes back down to a solution and an ending. Plan your mountain first and the writing becomes much easier.",
  blocks: [
    { type: "mountain", stages: [
      { title: "Beginning", text: "Introduce who, where and when. Hook the reader with a strong opening. Give a hint of the mood.", len: "1 paragraph", q: "Who is in the story? Where are they? When is it? What is the weather or mood like?" },
      { title: "Build-up", text: "Something starts to happen. Drop a clue that trouble is coming. Keep it moving.", len: "1 paragraph", q: "What are the characters doing? What do they notice? What small thing hints at the problem?" },
      { title: "Problem / Climax", text: "The most exciting, worrying or important part. Slow down here. Show feelings, use the senses and some dialogue.", len: "2 paragraphs (the longest part)", q: "What goes wrong? How does the main character feel? What do they see, hear and do? What choice must they make?" },
      { title: "Solution", text: "How is the problem solved? Who helps? What does the main character decide or do?", len: "1 paragraph", q: "What does the character decide to do? Who helps? How do people react?" },
      { title: "Ending", text: "Reflect on what happened. Show what was learnt, how the character feels now, or what will change.", len: "1 short paragraph", q: "What lesson was learnt? How do I feel now? Will I do anything differently? How does it link to the title?" }
    ] },
    { type: "tip", html: "<b>Spend words where it matters:</b> The top of the mountain is the problem and climax. That is where your best sentences, your feelings and your senses should go. The beginning and ending should be shorter." },
    { type: "cards", title: "Ask the 5W1H questions", items: [
      { tag: "Who", title: "Who is in the story?", text: "Choose one main character and two or three others at most. Too many characters make the story confusing.", ex: "Me, my little brother Ryan, and an elderly uncle." },
      { tag: "What", title: "What happens?", text: "What is the problem? What is the most exciting moment? This is the heart of your story.", ex: "I find a wallet stuffed with money and am tempted to keep it." },
      { tag: "Where", title: "Where does it happen?", text: "Pick a setting you know well so you can describe it with the senses.", ex: "A busy hawker centre near our HDB flat." },
      { tag: "When", title: "When does it happen?", text: "Time of day and weather can set the mood. A stormy night feels different from a sunny morning.", ex: "Saturday lunchtime, hot and crowded." },
      { tag: "Why", title: "Why does it happen?", text: "Why does the problem happen? Why does the character make that choice? This gives your story meaning.", ex: "I give it back because I see a photo of the owner and imagine how worried he must be." },
      { tag: "How", title: "How is it solved?", text: "How does the story end? How does the character change? Make the solution believable.", ex: "I spot the owner searching the floor and hand it back. He is overjoyed." }
    ] },
    { type: "text", title: "A worked example", html: "Here is a complete plan for the topic <b>“An Act of Honesty”</b>. Notice that it is written in short notes, not full sentences. It took about eight minutes." },
    { type: "cards", items: [
      { tag: "Stage 1", title: "Beginning", text: "Setting opening: busy hawker centre, Saturday lunch. Little brother Ryan and I eating noodles. Sounds: clattering plates, uncles calling orders. Smell: fried kway teow.", ex: "The hawker centre was buzzing. Plates clattered, uncles shouted out orders and the smell of fried kway teow drifted through the air." },
      { tag: "Stage 2", title: "Build-up", text: "I see something black under the next table. Pick it up: a leather wallet, thick with fifty-dollar notes. Eyes wide.", ex: "Curious, I bent down and picked it up. It was a leather wallet, thick with fifty-dollar notes." },
      { tag: "Stage 3", title: "Problem / Climax", text: "Ryan: “We’re rich! We can buy that new game!” I am tempted (heart thumping). Then I notice a photo inside: old man with a little girl. Heavy feeling in stomach. I decide: “This isn’t ours.”", ex: "For a moment, I was tempted. Then I noticed a small photo tucked inside, and a heavy feeling settled in my stomach." },
      { tag: "Stage 4", title: "Solution", text: "Spot old man from photo, searching the floor, hands trembling. Hurry over. “Excuse me, Uncle, is this yours?” His face lights up. He offers a reward; I politely refuse.", ex: "His whole face lit up. “Thank you, thank you!” he exclaimed, clutching the wallet to his chest." },
      { tag: "Stage 5", title: "Ending", text: "Walk home, warm proud feeling. Ryan: “That was better than any video game.” Lesson: honesty gives us something money cannot buy. Link to title.", ex: "That day, I learnt that honesty may cost us something we want, but it gives us something money cannot buy." },
      { tag: "Check", title: "Does it answer the question?", text: "Yes. The honest act (returning the wallet) is the climax, not a side event. The temptation makes the choice meaningful. The ending names the lesson.", ex: "My story is about returning a wallet, and it answers the question because the whole climax is my honest choice." }
    ] },
    { type: "tip", html: "<b>Plan the ending first:</b> Many good writers decide the lesson or final feeling before they plan anything else. Then every stage of the mountain can lead towards it." },
    { type: "rewrite", title: "Plan one stage", intro: "Each task gives you a topic and a stage of the story mountain. Write ONE line of plot notes for that stage. Then reveal a model answer. There are many good answers.", items: [
      { q: "Topic: “A Kind Act”. Write the <b>Problem / Climax</b> in one line.", a: "The lift at our block breaks down and old Madam Tan from the eighth floor is stuck at the bottom with three heavy bags of groceries, looking close to tears.", hint: "What goes wrong that gives someone the chance to be kind?" },
      { q: "Topic: “Lost in a Crowd”. Write the <b>Beginning</b> in one line.", a: "Sound opening: the drums of the Chingay parade boom as I hold Mum’s hand tightly in the huge crowd along the street.", hint: "Who, where, when, and a hook." },
      { q: "Topic: “A Mistake I Made”. Write the <b>Solution</b> in one line.", a: "I gather my courage, knock on Mr Rahman’s door and admit that it was my ball that cracked his window, offering to pay with my savings.", hint: "How does the main character put things right?" },
      { q: "Topic: “A Frightening Experience”. Write the <b>Build-up</b> in one line.", a: "At the chalet at night, Priya and I hear scratching at the back door, and the lights flicker as a storm rolls in.", hint: "Drop a clue that something is about to go wrong." },
      { q: "Topic: “An Act of Courage”. Write the <b>Ending</b> in one line.", a: "I learn that being brave does not mean having no fear; it means doing the right thing while your knees are still shaking.", hint: "What was learnt? Link to the title." },
      { q: "Topic: “The Missing Pet”. Write the <b>Problem / Climax</b> in one line.", a: "After hours of searching our estate, I hear a faint meow from a drain and spot Mochi trapped on a ledge just above the rising rainwater.", hint: "The most worrying moment. Make it tense." },
      { q: "Topic: “A Lesson Learnt”. Write the <b>Beginning</b> and <b>Problem</b> in one line each.", a: "Beginning: Speech opening, “Just one more level!” I beg Mum the night before my Science test.<br>Problem: The next morning I oversleep, rush to school without revising and freeze when I see the paper.", hint: "Plan the mistake that leads to the lesson." },
      { q: "Topic: “Helping a Stranger”. Write the <b>Solution</b> and <b>Ending</b> in one line each.", a: "Solution: I help the lost boy call his father on my phone and wait with him at the MRT station’s passenger service centre until his father rushes in.<br>Ending: Seeing the boy run into his father’s arms, I realise a few minutes of my time made a huge difference to a family.", hint: "How is the problem solved, and what does the helper feel or learn?" }
    ] }
  ] },

/* ===================== BUILDING BLOCKS ===================== */

{ id: "en-openings", group: "Building blocks", order: 20,
  title: "Openings that hook",
  intro: "Your first sentence decides whether the reader wants to keep going. Here are eight ways to open the same story about finding a wallet at a hawker centre.",
  blocks: [
    { type: "cards", items: [
      { tag: "Sound", title: "Start with a sound", text: "A sound word (onomatopoeia) wakes the reader up and puts them right in the scene.", ex: "Clang! A tray crashed to the floor behind me, and that was when I noticed something black under the table." },
      { tag: "Speech", title: "Start with speech", text: "Jump straight into a conversation. The reader wants to know who is speaking and why.", ex: "“Is that a wallet?” Ryan whispered, pointing under the next table." },
      { tag: "Action", title: "Start with action", text: "Drop the reader into the middle of something happening. Use a strong verb.", ex: "I dived under the table, and my fingers closed around a smooth leather wallet." },
      { tag: "Question", title: "Ask a question", text: "Make the reader think about what they would do. Keep it short and link it to the theme.", ex: "What would you do if you found two hundred dollars lying on the floor and nobody was watching?" },
      { tag: "Setting", title: "Paint the setting", text: "Use two or three senses to make the reader see, hear and smell the place.", ex: "The hawker centre was buzzing. Plates clattered, uncles shouted out orders and the smell of fried kway teow drifted through the air." },
      { tag: "Feeling", title: "Start with a feeling", text: "Show how the character feels through the body, so the reader is curious about why.", ex: "My heart was racing. In my hands was a wallet stuffed with money, and nobody had seen me pick it up." },
      { tag: "Flashback", title: "Start with a flashback", text: "Begin in the present, then look back to the event. It makes the story feel important.", ex: "Every time I walk past the noodle stall at Block 123, I remember the Saturday I found a stranger’s wallet, and the choice I almost got wrong." },
      { tag: "Surprise", title: "Start with a surprising statement", text: "Say something unexpected that makes the reader ask, “What? Why?”", ex: "The most valuable thing I ever found was worth two hundred dollars, and I gave every cent of it back." }
    ] },
    { type: "tip", html: "<b>Mix two hooks:</b> The strongest openings often combine two types. A sound plus action: “Crash! I spun around just as the tray hit the floor.” Speech plus feeling: “Don’t move,” Dad whispered. My heart thudded in my ears." },
    { type: "tip", html: "<b>Keep it short:</b> Your opening paragraph should be about three to five sentences. Hook the reader, show who and where, then move on towards the problem." },
    { type: "avoid", items: [
      "One day, I woke up, brushed my teeth and ate my breakfast.",
      "Hi, my name is Sarah and I am going to tell you a story.",
      "It was a sunny day. The birds were singing. (used in every story)",
      "This story is about the time I found a wallet.",
      "Once upon a time, there was a boy."
    ], note: "These openings waste words on things that do not matter, or give the whole story away. Start close to the action and make the reader curious." },
    { type: "rewrite", title: "Turn it into a hook", intro: "Each opening below is boring. Rewrite it using the hook named in brackets. Then compare with the model.", items: [
      { q: "One day, I went to the hawker centre with my brother. (Sound)", a: "Sizzle! Flames leapt from the wok as my brother and I squeezed past the char kway teow stall, searching for an empty table.", hint: "Begin with a sound word and an exclamation mark." },
      { q: "It was the first day of school and I was nervous. (Feeling)", a: "My stomach churned like a washing machine as I stood outside the classroom door, gripping the straps of my brand-new bag.", hint: "Show the nervousness through the body." },
      { q: "My mother asked me to clean my room. (Speech)", a: "“If I find one more sock under that bed, there will be no screen time for a week!” Mum called from the kitchen.", hint: "Start with the exact words she said." },
      { q: "We went to the beach. It was nice. (Setting)", a: "Waves rolled lazily onto the shore, the salty breeze tugged at my hair and the warm sand squished between my toes as we raced towards the water.", hint: "Use at least three senses." },
      { q: "One day, my friend and I saw a fire. (Action)", a: "I grabbed Aisha’s arm and pulled her back as thick black smoke billowed out of the kitchen window on the third floor.", hint: "Start in the middle of the action with a strong verb." },
      { q: "This story is about how I lost my dog. (Question)", a: "Have you ever searched every corner of your estate, calling a name until your voice cracked?", hint: "Ask a question that makes the reader imagine the situation." },
      { q: "I had a test and I did not study. (Surprising statement)", a: "I scored zero on my spelling test, and it was the best thing that ever happened to me.", hint: "Say something unexpected that makes the reader ask why." },
      { q: "I want to tell you about my grandmother. (Flashback)", a: "Whenever I smell pandan cake baking, I am back in Ah Ma’s tiny kitchen, the afternoon she taught me to be patient.", hint: "Start now, then look back." },
      { q: "It was raining and I was walking home. (Sound + Setting)", a: "Boom! Thunder shook the sky as raindrops the size of marbles drummed on my umbrella, and the path to my block disappeared into a grey blur.", hint: "Combine a sound word with what you see and feel." },
      { q: "One day, our class had a competition. (Speech + Feeling)", a: "“And the winner is…” Mrs Lim paused. I squeezed my eyes shut and crossed every finger I had.", hint: "Use a line of speech, then show how the character feels." }
    ] }
  ] },

{ id: "en-endings", group: "Building blocks", order: 21,
  title: "Endings with meaning",
  intro: "A strong ending tells the reader why the story mattered. Here are six ways to end the wallet story, and lots of practice turning flat endings into memorable ones.",
  blocks: [
    { type: "cards", items: [
      { tag: "Lesson", title: "The lesson learnt", text: "Say clearly what the character learnt, in your own words.", ex: "From that day on, I knew that being honest is always the right choice, even when no one is watching." },
      { tag: "Feeling", title: "The feeling now", text: "Show how the character feels after everything is over, using the body or senses.", ex: "As I lay in bed that night, a warm glow filled my chest. I had done the right thing, and nothing felt better." },
      { tag: "Circle back", title: "Circle back to the start", text: "Return to an image, sound or place from your opening, but show how it feels different now.", ex: "The next time we ate at that hawker centre, the clatter of plates sounded different. It was the place where I learnt to be honest." },
      { tag: "Promise", title: "A promise or resolution", text: "The character decides how they will act in future because of what happened.", ex: "I promised myself that I would always return what is not mine, no matter how tempted I feel." },
      { tag: "Saying", title: "A saying or proverb", text: "Sum up the lesson with a well-known saying, linked to a person in the story.", ex: "As we walked home, I finally understood what Mum meant when she said, “Honesty is the best policy.”" },
      { tag: "Last line", title: "A final line of dialogue or action", text: "End with a short moment that shows the change, so the reader works out the meaning.", ex: "Ryan nudged me and grinned. “That was better than any video game,” he admitted." }
    ] },
    { type: "tip", html: "<b>Link to the title:</b> Use a word or idea from the title in your last paragraph. If the title is “An Act of Honesty”, the word “honest” or “honesty” should appear near the end. It shows the marker your story answered the question." },
    { type: "tip", html: "<b>Combine two:</b> A feeling plus a lesson is a reliable ending. “A warm, proud feeling filled my chest. That day, I learnt that honesty gives us something money cannot buy.”" },
    { type: "avoid", items: [
      "Then I woke up. It was all a dream.",
      "The end.",
      "And they all lived happily ever after.",
      "I went home, had dinner, bathed and slept.",
      "It was a very fun day. I hope you liked my story.",
      "I learnt my lesson. (without saying WHAT the lesson was)"
    ], note: "These endings skip the lesson or feeling that makes a story memorable. The dream ending also cancels out everything that happened, which disappoints the reader." },
    { type: "rewrite", title: "Give it meaning", intro: "Rewrite each flat ending using the type named in brackets. Then compare with the model.", items: [
      { q: "Story: you were rude to a new classmate, then apologised. Ending: “Then we were friends. The end.” (Lesson)", a: "Today, Aisha is my closest friend. I often think how close I came to losing her before our friendship even began, and I have learnt that a few kind words on the first day can change everything.", hint: "Say what was learnt, in your own words." },
      { q: "Story: you were lost at the zoo and found by a zookeeper. Ending: “Then I went home.” (Feeling)", a: "In the taxi home, I held Mum’s hand the whole way. My legs were still a little wobbly, but my heart felt as light as a feather.", hint: "Show the feeling through the body." },
      { q: "Story: you scored badly in a test, then worked hard and improved. Ending: “I was happy.” (Promise)", a: "As I pinned the test onto my noticeboard, I made a promise to myself: I would never again leave my revision to the last minute.", hint: "What will the character do from now on?" },
      { q: "Story: it opened with rain at the void deck where you found an injured kitten. Ending: “I kept the kitten.” (Circle back)", a: "Months later, it rained again at the void deck. This time, a plump, purring Mochi sat dry and warm on my lap, watching the raindrops with me.", hint: "Bring back the rain and the void deck, but show the change." },
      { q: "Story: you rushed across a road and almost got hit. Ending: “I was more careful after that.” (Saying)", a: "Even now, before I step off a kerb, I can hear Dad’s voice in my head: “Look before you leap.” I will never forget how close I came.", hint: "Use a proverb linked to a person in the story." },
      { q: "Story: your little sister helped you finish a project on time. Ending: “It was a good day.” (Last line)", a: "That evening, I peeled the gold star off our poster and stuck it on Mei Ling’s forehead. She giggled and wore it proudly all through dinner.", hint: "End with a small moment that shows the meaning." },
      { q: "Story: you told a lie and got caught. Ending: “Then I woke up. It was a dream.” (Feeling + Lesson)", a: "As Mum hugged me, the heavy weight in my chest finally lifted. I had learnt that one small lie can grow into a mountain of trouble, and that the truth, however scary, is always lighter to carry.", hint: "No dream! Show the relief, then name the lesson." },
      { q: "Story: you helped an old man who fell at the MRT station. Ending: “I helped him. I am kind.” (Lesson + Circle back)", a: "Every time I pass that MRT station now, I glance at the spot where Mr Goh fell. I learnt that kindness does not need a plan. It only needs someone who is willing to stop.", hint: "Return to the place, then share the lesson." }
    ] }
  ] },

{ id: "en-paragraphs", group: "Building blocks", order: 22,
  title: "Paragraphs",
  intro: "Paragraphs are like rooms in a house. Each one holds one part of the story, and a new one tells the reader that something has changed.",
  blocks: [
    { type: "text", html: "A story without paragraphs is like a wall of text: tiring to read and hard to follow. Good paragraphs help the reader know when something new is happening. Use the <b>TiPToP</b> rule to remember when to start a new one: <b>Ti</b>me, <b>P</b>lace, <b>To</b>pic (a new event), <b>P</b>erson speaking. Add one more: a change in <b>mood</b>." },
    { type: "cards", title: "When to start a new paragraph", items: [
      { tag: "Time", title: "When time moves on", text: "Start a new paragraph when the story jumps forward or back in time.", ex: "…and I fell asleep.<br><br>The next morning, a loud knock woke me up." },
      { tag: "Place", title: "When the place changes", text: "Start a new paragraph when the characters move somewhere new.", ex: "…we hurried out of the classroom.<br><br>The school hall was already packed with noisy pupils." },
      { tag: "Speaker", title: "When a new person speaks", text: "Every time a different person speaks, start a new line, even if they only say one word.", ex: "“Is this yours?” I asked.<br><br>“Yes!” the old man cried." },
      { tag: "Event", title: "When something new happens", text: "A new event or problem gets its own paragraph so the reader feels the change.", ex: "…we were laughing at Ryan’s joke.<br><br>Just then, the lights went out." },
      { tag: "Mood", title: "When the mood changes", text: "When the feeling of the story shifts, from happy to scared or from tense to relieved, start fresh.", ex: "…everyone cheered and clapped.<br><br>But when I looked down, my medal was gone." }
    ] },
    { type: "cards", title: "Topic sentences", items: [
      { tag: "What", title: "Start each paragraph with a clear sentence", text: "The first sentence of a paragraph tells the reader what the paragraph is about. In stories, it often moves the action forward or sets the scene.", ex: "Without wasting another second, I hurried over to the old man." },
      { tag: "Linking", title: "Use connectors to link paragraphs", text: "Words like “Moments later”, “Just then”, “Meanwhile” and “That evening” help the reader move smoothly from one paragraph to the next.", ex: "Moments later, a frantic voice echoed across the hawker centre." },
      { tag: "Focus", title: "One main idea per paragraph", text: "Keep each paragraph about one thing. If you find yourself writing about something new, it is time for a new paragraph.", ex: "Paragraph about finding the wallet; next paragraph about the temptation; next about the decision." }
    ] },
    { type: "cards", title: "Balance your story", items: [
      { tag: "Short", title: "Beginning: short", text: "One paragraph of about three to five sentences. Hook, who, where, and on you go.", ex: "About 10–15% of your words." },
      { tag: "Medium", title: "Build-up: medium", text: "One paragraph that leads towards the problem.", ex: "About 15–20% of your words." },
      { tag: "Longest", title: "Problem and climax: the longest", text: "Two paragraphs or more. Slow down. Show feelings, use senses and dialogue. This is the heart of your story.", ex: "About 40–50% of your words." },
      { tag: "Medium", title: "Solution: medium", text: "One paragraph showing how the problem is solved.", ex: "About 15–20% of your words." },
      { tag: "Short", title: "Ending: short but strong", text: "A few sentences that show the feeling and the lesson.", ex: "About 10% of your words." }
    ] },
    { type: "tip", html: "<b>The slow-motion trick:</b> At the climax, slow time down. Instead of “I caught the vase”, write what you saw, heard and felt, second by second: “The vase wobbled. I lunged forward, arms outstretched. My fingertips brushed the cold glass, and then, with a thud, it landed safely in my palms.”" },
    { type: "tip", html: "<b>Check your page:</b> When you finish, look at the shape of your story. If the beginning is the longest paragraph and the climax is two lines, you have spent your words in the wrong place." },
    { type: "mcq", title: "Where should a new paragraph start?", intro: "Decide where a new paragraph is needed, and why.", items: [
      { q: "“…I finished my homework and went to bed. The next morning, I woke up to the sound of sirens.” Should there be a new paragraph?", o: ["No, it is the same story.", "Yes, before “The next morning”, because time has moved on.", "Yes, before “and went to bed”."], a: 1, e: "A jump in time (from night to the next morning) is a signal to start a new paragraph." },
      { q: "“Where is my bag?” Mei Ling asked. “I saw it in the canteen,” Priya replied. How should this be set out?", o: ["Keep it on one line.", "Put Priya’s words on a new line.", "Put both sentences in brackets."], a: 1, e: "Each time a new person speaks, start a new line." },
      { q: "Which sentence should start a NEW paragraph in a story about a picnic?", o: ["We spread the mat on the grass.", "Mum handed out sandwiches.", "Without warning, dark clouds rolled in and the first drops of rain splattered on our food."], a: 2, e: "A new event that changes the mood (from happy picnic to sudden storm) deserves a new paragraph." },
      { q: "Which part of a story should usually be the LONGEST?", o: ["The problem and climax", "The beginning", "The ending"], a: 0, e: "The climax is the most exciting part. Slow down and spend the most words there." },
      { q: "“…we waved goodbye at the school gate. At home, Grandma was waiting with a bowl of hot soup.” Why start a new paragraph before “At home”?", o: ["Because a new person speaks.", "Because the place has changed.", "Because it is a question."], a: 1, e: "The story moves from the school gate to home, so the place has changed." },
      { q: "Which is the best topic sentence to start a paragraph about the climax?", o: ["It was a normal day.", "I like ice cream very much.", "Just then, a piercing scream rang out from the playground."], a: 2, e: "This sentence moves the action forward and tells the reader something exciting is about to happen." },
      { q: "A pupil writes the whole story in one huge paragraph. What is the main problem?", o: ["The story will be too short.", "The reader cannot easily tell when time, place, speaker or events change.", "There is no problem."], a: 1, e: "Paragraphs signal changes. Without them, the story is hard to follow." },
      { q: "“…everyone sang Happy Birthday and clapped. When I opened the box, my smile disappeared. It was empty.” Where should the new paragraph start?", o: ["Before “When I opened the box”, because the mood changes.", "Before “It was empty”.", "Before “and clapped”."], a: 0, e: "The mood shifts from joy to disappointment at “When I opened the box”. That is where the new paragraph belongs." }
    ] }
  ] },

{ id: "en-sentences", group: "Building blocks", order: 23,
  title: "Sentence power",
  intro: "Good writers mix different kinds of sentences, like a drummer mixing fast and slow beats. Learn the three sentence types and eight ways to start a sentence.",
  blocks: [
    { type: "cards", title: "Three kinds of sentences", items: [
      { tag: "Simple", title: "Simple sentence", text: "One idea, one main verb. Short and punchy. Great for tension and surprise.", ex: "The lights went out." },
      { tag: "Compound", title: "Compound sentence", text: "Two simple sentences joined by a connector (a joining word) such as and, but, or, so, yet. Use a comma before the joining word when both halves are long.", ex: "I wanted to keep the money, but I knew it was wrong." },
      { tag: "Complex", title: "Complex sentence", text: "A main idea plus an extra part that cannot stand alone, joined by words like when, because, although, while, as, if, after, before.", ex: "Although my legs were trembling, I stepped forward and raised my hand." }
    ] },
    { type: "tip", html: "<b>Mix them up:</b> Three long sentences in a row feel slow. Three short ones in a row feel choppy. The best writing mixes them: a long sentence to describe, then a short one to punch." },
    { type: "cards", title: "Eight ways to start a sentence", items: [
      { tag: "-ing", title: "Start with an -ing word", text: "Shows two actions happening at the same time. Put a comma after the -ing part.", ex: "Clutching the wallet tightly, I scanned the crowded hawker centre." },
      { tag: "-ed", title: "Start with an -ed word", text: "Usually describes how the character feels. Follow it with a comma.", ex: "Exhausted, Jun Hao collapsed onto the bench at the void deck." },
      { tag: "Adverb", title: "Start with an adverb", text: "An -ly word shows HOW something is done.", ex: "Slowly, the door creaked open." },
      { tag: "Preposition", title: "Start with a preposition", text: "Words like under, behind, across, beneath, above tell the reader WHERE.", ex: "Under the next table, something black caught my eye." },
      { tag: "Simile", title: "Start with a simile", text: "A comparison using “like” or “as” paints a picture straight away.", ex: "Like a frightened rabbit, the little boy darted behind his mother." },
      { tag: "Sound", title: "Start with a sound", text: "A sound word grabs attention, especially at exciting moments.", ex: "Crash! The tray of drinks smashed onto the floor." },
      { tag: "Short", title: "Start with a short sentence", text: "A very short sentence, even one or two words, creates drama.", ex: "Silence. Nobody dared to breathe." },
      { tag: "Question", title: "Start with a question", text: "A question shows what the character is thinking and pulls the reader in.", ex: "Who would leave so much money lying on the floor?" }
    ] },
    { type: "cards", title: "Short sentences for tension", items: [
      { tag: "Before", title: "All long sentences", text: "When everything is long, the exciting part feels slow.", ex: "I heard footsteps behind me in the dark corridor and I turned around slowly to see who it was but there was nobody there." },
      { tag: "After", title: "Long, then short", text: "Build up with a longer sentence, then hit the reader with short ones.", ex: "As I tiptoed down the dark corridor, footsteps echoed behind me. I froze. I turned. Nobody was there." }
    ] },
    { type: "tip", html: "<b>Do not overdo it:</b> Use special sentence starters a few times in a story, not in every sentence. If every sentence starts with an -ing word, it becomes tiring to read." },
    { type: "rewrite", title: "Combine the sentences", intro: "Join the short sentences into ONE better sentence. Use a connector such as and, but, so, because, when, although, while, or an -ing word.", items: [
      { q: "I saw a wallet. It was under the table. It was black.", a: "I saw a black wallet under the table.", hint: "Put the describing words together in one sentence." },
      { q: "It was raining heavily. We stayed indoors.", a: "Because it was raining heavily, we stayed indoors.", hint: "Try “because” or “so”." },
      { q: "I wanted to play outside. I had to finish my homework.", a: "I wanted to play outside, but I had to finish my homework.", hint: "These ideas contrast. Use “but”." },
      { q: "Mei Ling was tired. She kept running. She wanted to finish the race.", a: "Although she was tired, Mei Ling kept running because she wanted to finish the race.", hint: "Try “although” and “because”." },
      { q: "The bell rang. The pupils rushed out of the classroom.", a: "As soon as the bell rang, the pupils rushed out of the classroom.", hint: "Show that one thing happened right after the other." },
      { q: "Grandpa sat on the bench. He was reading the newspaper. He was sipping kopi.", a: "Grandpa sat on the bench, reading the newspaper and sipping his kopi.", hint: "Use -ing words for actions happening at the same time." },
      { q: "I opened the door. I saw a huge cake. Everyone shouted, “Surprise!”", a: "When I opened the door, I saw a huge cake as everyone shouted, “Surprise!”", hint: "Try “when” and “as”." },
      { q: "The boy fell off his bicycle. He hurt his knee. He did not cry.", a: "The boy fell off his bicycle and hurt his knee, but he did not cry.", hint: "Use “and” for the first two, “but” for the surprise." },
      { q: "Dad was cooking dinner. The doorbell rang.", a: "While Dad was cooking dinner, the doorbell rang.", hint: "Use “while” to show something interrupted another action." },
      { q: "Aisha studied hard. She did well in her test. Her parents were proud.", a: "Aisha studied hard, so she did well in her test and made her parents proud.", hint: "Show cause and effect with “so”." }
    ] },
    { type: "rewrite", title: "Expand the sentence", intro: "Make each plain sentence richer by adding WHEN it happened, WHERE it happened and HOW it happened.", items: [
      { q: "The dog barked.", a: "In the middle of the night, the neighbour’s dog barked furiously outside our door.", hint: "When? Where? How?" },
      { q: "I ran.", a: "As soon as the bell rang, I ran breathlessly across the field to the school gate.", hint: "Add a time, a place and a manner (-ly word)." },
      { q: "She cried.", a: "After reading the letter, Priya cried quietly in the corner of her bedroom.", hint: "When did she cry, where, and how?" },
      { q: "The boy found a wallet.", a: "On Saturday afternoon, the boy found a thick leather wallet lying under a table at the busy hawker centre.", hint: "Add when, where, and describe the wallet." },
      { q: "We ate.", a: "That evening, we ate hungrily around the small table in Grandma’s kitchen.", hint: "Think of a family scene." },
      { q: "The rain fell.", a: "Without warning, the rain fell heavily on the roof of the bus shelter.", hint: "How did it fall? Onto what?" },
      { q: "He waited.", a: "For almost an hour, Wei Ming waited nervously outside the principal’s office.", hint: "How long? Where? How did he feel?" },
      { q: "The crowd cheered.", a: "When the final whistle blew, the crowd cheered wildly from the stands of the stadium.", hint: "When? Where? How loudly?" },
      { q: "I opened the box.", a: "With trembling hands, I slowly opened the box on the kitchen table after dinner.", hint: "Show how the character felt as well." },
      { q: "The cat jumped.", a: "Just as I reached out, the cat jumped gracefully from the windowsill onto the top of the cupboard.", hint: "When? From where to where? How?" }
    ] },
    { type: "rewrite", title: "Change the sentence starter", intro: "Each sentence starts with “I” or “The”. Rewrite it using the starter in brackets.", items: [
      { q: "I held my breath and opened the door. (-ing word)", a: "Holding my breath, I opened the door.", hint: "Start with “Holding…” and add a comma." },
      { q: "I was terrified and could not move. (-ed word)", a: "Terrified, I could not move a single muscle.", hint: "Start with the feeling word and a comma." },
      { q: "The old man walked across the road carefully. (adverb)", a: "Carefully, the old man shuffled across the road.", hint: "Move the -ly word to the front." },
      { q: "The kitten was hiding behind the rubbish bin. (preposition)", a: "Behind the rubbish bin, a tiny kitten was hiding.", hint: "Start with “Behind…”." },
      { q: "The boy ran out of the room very fast. (simile)", a: "Like a bolt of lightning, the boy shot out of the room.", hint: "Start with “Like a…”." },
      { q: "The glass fell and broke. (sound)", a: "Smash! The glass shattered into a hundred pieces.", hint: "Start with a sound word and an exclamation mark." },
      { q: "I looked inside the cupboard and it was empty. (short sentence)", a: "Empty. I stared into the cupboard in disbelief.", hint: "Start with a one-word sentence." },
      { q: "I wondered who had left the gate open. (question)", a: "Who had left the gate open? My eyes darted up and down the empty corridor.", hint: "Turn the wondering into a real question." }
    ] }
  ] },

{ id: "en-dialogue", group: "Building blocks", order: 24,
  title: "Writing dialogue",
  intro: "Dialogue lets your characters speak. It makes a story feel real and alive, but only when it is punctuated properly and used at the right moments.",
  blocks: [
    { type: "cards", title: "Seven rules of dialogue", items: [
      { tag: "Rule 1", title: "Use speech marks", text: "Put the exact words spoken inside speech marks (inverted commas).", ex: "“Where is my bag?” asked Tom." },
      { tag: "Rule 2", title: "Start with a capital letter", text: "The first spoken word always starts with a capital letter, even in the middle of a sentence.", ex: "Mum said, “Dinner is ready.”" },
      { tag: "Rule 3", title: "Punctuation goes inside", text: "Commas, full stops, question marks and exclamation marks go INSIDE the closing speech mark.", ex: "“Watch out!” shouted Ben." },
      { tag: "Rule 4", title: "Comma, not full stop, before the speaker", text: "If the speaker comes after the spoken words, end the speech with a comma (unless it is a question or exclamation).", ex: "“Let’s go,” said Dad." },
      { tag: "Rule 5", title: "Comma before speech", text: "If the speaker comes first, put a comma before the opening speech mark.", ex: "Priya whispered, “I think someone’s behind the door.”" },
      { tag: "Rule 6", title: "New speaker, new line", text: "Start a new line each time a different person speaks.", ex: "“Are you okay?” asked Mei Ling.<br>“I think so,” I replied, rubbing my knee." },
      { tag: "Rule 7", title: "Split speech carefully", text: "When the speaker comes in the middle of one sentence, the second part starts with a small letter.", ex: "“If we hurry,” said Wei Ming, “we can still catch the bus.”" }
    ] },
    { type: "tip", html: "<b>Action instead of “said”:</b> Sometimes the best tag is no tag at all. Show an action next to the speech, and the reader knows who is talking. “Wait!” Ben grabbed my arm. “Don’t open that door.”" },
    { type: "tip", html: "<b>Keep it short and useful:</b> Use dialogue only when it moves the story forward or shows a feeling. Two or three short exchanges at the key moments are better than a whole page of chatting." },
    { type: "table", title: "Twenty words instead of “said”", head: ["Mood", "Words"], rows: [
      ["Happy", "laughed, giggled, cheered, chuckled"],
      ["Sad", "sobbed, sniffled, wailed, sighed"],
      ["Angry", "snapped, growled, yelled, snarled"],
      ["Scared or nervous", "stammered, whimpered, gasped, squeaked"],
      ["Quiet or secret", "whispered, murmured, muttered, mumbled"]
    ] },
    { type: "tip", html: "<b>Choose words that fit:</b> “Sobbed” only works if the person is crying. “Giggled” only works if something is funny. A word that does not fit the mood is worse than plain “said”." },
    { type: "mcq", title: "Dialogue quiz", intro: "Choose the correct answer.", items: [
      { q: "Which sentence is punctuated correctly?", o: ["“Hurry up.” said Mum.", "“Hurry up,” said Mum.", "“Hurry up”, said Mum."], a: 1, e: "Use a comma inside the speech marks when the speaker comes after." },
      { q: "Which one is correct?", o: ["Ali asked, “where is the library?”", "Ali asked “Where is the library”?", "Ali asked, “Where is the library?”"], a: 2, e: "Spoken words start with a capital letter, and the question mark goes inside the speech marks." },
      { q: "Which is the most interesting dialogue?", o: ["“Help!” Sam screamed, clinging to the branch.", "“Help,” said Sam.", "“Help!” said Sam."], a: 0, e: "A strong verb plus an action shows the reader what is happening." },
      { q: "Which split sentence is correct?", o: ["“I know,” said Jun Hao, “Where the key is.”", "“I know.” said Jun Hao “where the key is.”", "“I know,” said Jun Hao, “where the key is.”"], a: 2, e: "When one sentence is split, the second part continues with a small letter after a comma." },
      { q: "Two people are talking. How should you set it out?", o: ["Start a new line each time the speaker changes.", "Put everything in one paragraph.", "Put each person’s words in brackets."], a: 0, e: "New speaker, new line. It helps the reader follow who is talking." },
      { q: "Which word best fits? “I-I didn’t do it,” he ___, staring at the floor.", o: ["cheered", "stammered", "laughed"], a: 1, e: "The broken “I-I” and staring at the floor show nervousness, so “stammered” fits." },
      { q: "Which sentence is correct?", o: ["Mum shouted, “Come down for dinner!”", "Mum shouted “come down for dinner!”", "Mum shouted, “Come down for dinner”!"], a: 0, e: "Comma before the speech, capital letter to start, exclamation mark inside." },
      { q: "Which is the best use of dialogue in a story?", o: ["“Hello.” “Hello.” “How are you?” “Fine.” “Good.”", "“Don’t touch that wire!” Dad yelled, yanking my hand away.", "“I am going to the shop now,” I said. “Okay,” said Mum."], a: 1, e: "Good dialogue moves the story forward and shows feeling. The others are just small talk." },
      { q: "Priya asks a question. Which sentence is punctuated correctly?", o: ["“Did you see that”? asked Priya.", "“Did you see that,” asked Priya?", "“Did you see that?” asked Priya."], a: 2, e: "The question mark belongs to the spoken words, so it goes inside the speech marks. No extra comma is needed." },
      { q: "Which one shows who is speaking WITHOUT using “said”?", o: ["“I won!” said Mei Ling.", "“I won!” Mei Ling said happily.", "Mei Ling waved her certificate in the air. “I won!”"], a: 2, e: "The action (waving the certificate) tells us who is speaking and how she feels." }
    ] },
    { type: "fixit", title: "Fix the dialogue", intro: "Each sentence has a punctuation mistake. Write it correctly, then check.", items: [
      { wrong: "“I’m hungry.” said Ryan.", right: "“I’m hungry,” said Ryan.", why: "When the speaker comes after, use a comma, not a full stop, inside the speech marks." },
      { wrong: "Mum said “It’s time for bed.”", right: "Mum said, “It’s time for bed.”", why: "Put a comma before the opening speech mark when the speaker comes first." },
      { wrong: "“where are you going?” asked Dad.", right: "“Where are you going?” asked Dad.", why: "Spoken words must start with a capital letter." },
      { wrong: "“Watch out”! shouted Aisha.", right: "“Watch out!” shouted Aisha.", why: "The exclamation mark belongs inside the speech marks." },
      { wrong: "Wei Ming asked, “Can I borrow your pencil”?", right: "Wei Ming asked, “Can I borrow your pencil?”", why: "The question mark goes inside the closing speech mark." },
      { wrong: "“If it rains,” said Mum, “We’ll stay at home.”", right: "“If it rains,” said Mum, “we’ll stay at home.”", why: "When one sentence is split, the second part continues with a small letter." },
      { wrong: "“Are you hurt?” asked the teacher. “No, I’m okay,” replied Jun Hao.", right: "“Are you hurt?” asked the teacher.<br>“No, I’m okay,” replied Jun Hao.", why: "Start a new line when a new person speaks." },
      { wrong: "I can’t find my wallet! cried the old man.", right: "“I can’t find my wallet!” cried the old man.", why: "The exact words someone says need speech marks around them." },
      { wrong: "“Thank you,” said Grandma “that’s very kind of you.”", right: "“Thank you,” said Grandma. “That’s very kind of you.”", why: "These are two separate sentences, so put a full stop after Grandma and start the next speech with a capital." },
      { wrong: "Priya whispered, “Is someone there”.", right: "Priya whispered, “Is someone there?”", why: "It is a question, so it needs a question mark, and it goes inside the speech marks." }
    ] }
  ] },

{ id: "en-grammar", group: "Building blocks", order: 25,
  title: "Fix common mistakes",
  intro: "Small mistakes can spoil a great story. Learn the six mistakes that pop up most often in compositions, and train your eyes to catch them.",
  blocks: [
    { type: "cards", items: [
      { tag: "Tense", title: "Stay in the past tense", text: "Stories are usually told in the past tense. Once you start in the past, stay there. The main exception is speech: inside speech marks, people can speak in the present tense.", ex: "Wrong: I <b>run</b> to the gate and <b>saw</b> my friend.<br>Right: I <b>ran</b> to the gate and <b>saw</b> my friend.<br>Inside speech is fine: “I <b>am</b> late!” I cried." },
      { tag: "Agreement", title: "Subject-verb agreement", text: "One person or thing takes a singular verb; more than one takes a plural verb. Watch out for “each”, “everyone” and “one of”, which are singular.", ex: "Wrong: Each of the boys <b>were</b> given a medal.<br>Right: Each of the boys <b>was</b> given a medal." },
      { tag: "Run-on", title: "Run-on sentences", text: "Two complete sentences cannot be joined with just a comma or nothing at all. Use a full stop, a connector, or a semicolon.", ex: "Wrong: It started to rain, we ran home.<br>Right: It started to rain, so we ran home.<br>Also right: It started to rain. We ran home." },
      { tag: "Its / it’s", title: "Its or it’s?", text: "<b>It’s</b> means “it is” or “it has”. <b>Its</b> means “belonging to it”. Test: if you can say “it is”, use it’s.", ex: "<b>It’s</b> raining. The cat licked <b>its</b> paw." },
      { tag: "There / their / they’re", title: "Three that sound the same", text: "<b>There</b> is a place (and in “there is”). <b>Their</b> means belonging to them. <b>They’re</b> means “they are”.", ex: "<b>They’re</b> putting <b>their</b> bags over <b>there</b>." },
      { tag: "Spelling", title: "Commonly misspelt words", text: "These words trip up many pupils. Learn them by heart: <b>because, beautiful, believe, friend, until, finally, suddenly, surprise, embarrassed, necessary, separate, disappear, immediately, tomorrow, already, which, whether, receive, decided, really</b>.", ex: "Tricks: a <b>friend</b> stays to the <b>end</b>. <b>Believe</b>: never be<b>lie</b>ve a <b>lie</b>. <b>Necessary</b>: one Collar, two Sleeves." }
    ] },
    { type: "tip", html: "<b>Irregular past tenses:</b> Many common verbs do not add -ed. Learn these: ran, came, went, saw, took, gave, caught, brought, thought, fought, bought, taught, felt, kept, slept, wrote, rode, chose, froze, threw, drew, fell, held, stood, understood, hid, bit, shook, began, swam." },
    { type: "tip", html: "<b>The checking trick:</b> In your last five minutes, read your story three times, each time hunting for one thing: first verbs (are they all past tense?), then sentence ends (any run-ons?), then tricky words (its, there, spelling)." },
    { type: "fixit", title: "Spot and fix", intro: "Each sentence has one or more mistakes. Write the correct version, then check.", items: [
      { wrong: "Yesterday, I go to the market with my mother.", right: "Yesterday, I went to the market with my mother.", why: "“Yesterday” tells us it is in the past, so use the past tense “went”." },
      { wrong: "I opened the door and see a huge spider.", right: "I opened the door and saw a huge spider.", why: "Keep both verbs in the past tense: opened, saw." },
      { wrong: "She catched the ball with one hand.", right: "She caught the ball with one hand.", why: "“Catch” is irregular. Its past tense is “caught”." },
      { wrong: "My brother and I was very excited.", right: "My brother and I were very excited.", why: "“My brother and I” is two people, so use the plural “were”." },
      { wrong: "Each of the pupils have a library card.", right: "Each of the pupils has a library card.", why: "“Each” is singular, so it takes “has”." },
      { wrong: "The box of biscuits were on the table.", right: "The box of biscuits was on the table.", why: "The subject is “the box” (one box), so use “was”." },
      { wrong: "It was getting dark, we hurried home.", right: "It was getting dark, so we hurried home.", why: "Two sentences joined only by a comma is a run-on. Add “so” or use a full stop." },
      { wrong: "I was tired I went to bed early.", right: "I was tired, so I went to bed early.", why: "These are two complete sentences. Join them with a connector or separate them." },
      { wrong: "The dog wagged it’s tail.", right: "The dog wagged its tail.", why: "The tail belongs to the dog, so use “its” (no apostrophe)." },
      { wrong: "Its going to rain soon.", right: "It’s going to rain soon.", why: "This means “It is going to rain”, so use “it’s”." },
      { wrong: "The children left there bags in the hall.", right: "The children left their bags in the hall.", why: "The bags belong to the children, so use “their”." },
      { wrong: "Their going to the zoo tomorrow.", right: "They’re going to the zoo tomorrow.", why: "This means “They are going”, so use “they’re”." },
      { wrong: "I put the plates over their.", right: "I put the plates over there.", why: "“There” is a place." },
      { wrong: "Suddenly, the lights went out and everyone screamed and I grabbed my sister’s hand and we ran.", right: "Suddenly, the lights went out. Everyone screamed. I grabbed my sister’s hand, and we ran.", why: "Too many “and”s make one long, breathless sentence. Break it into shorter sentences for more drama." },
      { wrong: "I didn’t beleive my eyes when I saw my freind.", right: "I didn’t believe my eyes when I saw my friend.", why: "Spelling: believe (i before e), friend (a friend stays to the end)." },
      { wrong: "We waited untill the rain stopped.", right: "We waited until the rain stopped.", why: "“Until” has only one l." },
      { wrong: "I was so embarased when I tripped on stage.", right: "I was so embarrassed when I tripped on stage.", why: "“Embarrassed” has double r and double s." },
      { wrong: "Finaly, the bus arrived and we was all relieved.", right: "Finally, the bus arrived and we were all relieved.", why: "“Finally” has double l, and “we” takes “were”." },
      { wrong: "Mum gived me a hug and tell me she was proud.", right: "Mum gave me a hug and told me she was proud.", why: "Past tense of “give” is “gave” and of “tell” is “told”." },
      { wrong: "Everyone in the class were laughing, it was so funny.", right: "Everyone in the class was laughing. It was so funny.", why: "“Everyone” is singular (was), and the comma creates a run-on, so use a full stop." }
    ] }
  ] },

{ id: "en-situational", group: "Building blocks", order: 26,
  title: "Situational writing",
  intro: "For upper primary: sometimes you write an email or letter for a real purpose, like asking for something or giving information. Here is how to get the tone and the details right.",
  blocks: [
    { type: "text", html: "In situational writing, you are given a situation, a short piece of information (such as a poster or notice) and a task. You must write an email, letter or note that includes all the important details. The secret is to remember <b>PAC</b>: Purpose, Audience and Context." },
    { type: "cards", title: "Remember PAC", items: [
      { tag: "P", title: "Purpose: why am I writing?", text: "Are you asking, informing, inviting, thanking, apologising or complaining? State your purpose clearly near the start of your email.", ex: "I am writing to ask whether our class may use the school hall for a charity sale." },
      { tag: "A", title: "Audience: who am I writing to?", text: "Your reader decides your tone. A principal, a company or someone you do not know needs a formal tone. A friend or cousin can get an informal, friendly tone.", ex: "To the principal: “Dear Mrs Lim”.<br>To a friend: “Hi Aisha!”" },
      { tag: "C", title: "Context: what is the situation?", text: "What happened, and what details does the reader need? Read the information given carefully and include every point the task asks for.", ex: "The date, time, venue, number of people and what you need." }
    ] },
    { type: "cards", title: "Formal or informal?", items: [
      { tag: "Formal", title: "For adults you do not know well", text: "Use full words (not short forms), polite phrases, no slang, no exclamation marks in every line. Sign off with your full name.", ex: "I would be grateful if you could let me know whether the venue is available on Saturday, 14 March." },
      { tag: "Informal", title: "For friends and family", text: "You can be warm and chatty, use short forms like “I’m” and “can’t”, and ask friendly questions. You still need correct grammar and all the details.", ex: "Hey Jun Hao! Guess what? Our class is having a charity sale next Saturday and I’d love you to come!" }
    ] },
    { type: "steps", title: "The structure of an email or letter", items: [
      { title: "Greeting", text: "Formal: “Dear Mr Tan,” or “Dear Sir or Madam,”. Informal: “Hi Priya,” or “Dear Grandma,”." },
      { title: "Purpose", text: "In the first paragraph, introduce yourself if needed and say why you are writing. Do not make the reader guess." },
      { title: "Details", text: "In one or two paragraphs, give all the important information: what, when, where, who, how many, and what you need. Answer every point in the task." },
      { title: "Closing", text: "Say what you hope will happen next and thank the reader. Formal: “Thank you for your time. I look forward to your reply.” then “Yours sincerely,” and your full name. Informal: “See you soon!” then your first name." }
    ] },
    { type: "chips", title: "Useful formal phrases", groups: [
      { title: "Opening the purpose", words: ["I am writing to ask about", "I am writing to inform you that", "I would like to request", "I am writing on behalf of my class", "I am writing to thank you for"], ex: "I am writing on behalf of Primary 5 Kindness to request the use of the school hall." },
      { title: "Asking politely", words: ["Could you please", "I would be grateful if", "Would it be possible to", "May I kindly ask"], ex: "I would be grateful if you could reply by Friday, 6 March." },
      { title: "Giving details", words: ["The event will be held on", "It will take place at", "We expect about", "Please note that", "In addition,"], note: "Use these to make sure every detail from the task is included." },
      { title: "Apologising", words: ["I sincerely apologise for", "I am very sorry for any inconvenience caused", "It was not my intention to"] },
      { title: "Closing", words: ["Thank you for your time and help.", "I look forward to your reply.", "Please let me know if you need more information.", "Yours sincerely,"], note: "Use “Yours sincerely” when you know the person’s name, and “Yours faithfully” when you started with “Dear Sir or Madam”." }
    ] },
    { type: "text", title: "An example email", html: "<b>Situation:</b> Your class wants to hold a charity book sale. Write an email to the school principal, Mrs Lim, to ask for permission to use the school canteen. Include the date, time, purpose and what help you need." },
    { type: "text", html: "<b>To:</b> Mrs Lim (Principal)<br><b>Subject:</b> Request to use the canteen for a charity book sale" },
    { type: "text", html: "Dear Mrs Lim," },
    { type: "text", html: "I am Wei Ming, the class monitor of Primary 5 Kindness. I am writing on behalf of my class to request permission to use the school canteen for a charity book sale." },
    { type: "text", html: "The sale will be held on Friday, 20 March, from 10.00 a.m. to 11.00 a.m., during the recess periods. We plan to sell second-hand storybooks donated by our classmates. All the money raised will be given to a home for the elderly near our school." },
    { type: "text", html: "We would be grateful if we could borrow four tables from the canteen. Our form teacher, Mr Rahman, has kindly agreed to supervise us. We will make sure the canteen is clean and tidy when the sale is over." },
    { type: "text", html: "Thank you for your time and consideration. I look forward to your reply.<br><br>Yours sincerely,<br>Tan Wei Ming<br>Class Monitor, Primary 5 Kindness" },
    { type: "tip", html: "<b>Tick the details:</b> Before you write, list every point the task asks for and tick each one off as you include it. In the example above: date (tick), time (tick), purpose (tick), help needed (tick). A missing detail is the most common way to lose marks for content." },
    { type: "mcq", title: "Tone and audience", intro: "Choose the best answer.", items: [
      { q: "You are writing to the manager of a bowling alley to book lanes for your class. Which greeting is best?", o: ["Hey there!", "Dear Sir or Madam,", "Yo manager,"], a: 1, e: "You do not know the manager’s name and this is formal, so use “Dear Sir or Madam,”." },
      { q: "Which sentence is best for an email to your principal?", o: ["Can we use the hall? Pls reply asap!!!", "We wanna use the hall, ok?", "I would be grateful if our class could use the hall on Friday, 13 March."], a: 2, e: "This is polite and formal, with full words and a clear detail (the date)." },
      { q: "You are inviting your cousin to your birthday party. Which tone should you use?", o: ["Informal and friendly", "Very formal", "Rude and short"], a: 0, e: "Your cousin is family, so a warm, informal tone is right." },
      { q: "Which sentence states the PURPOSE most clearly?", o: ["I hope you are well.", "I am writing to inform you that I have found your lost dog.", "The weather has been very hot lately."], a: 1, e: "It tells the reader straight away why you are writing." },
      { q: "Which closing goes with the greeting “Dear Mr Goh,”?", o: ["Love,", "Bye!", "Yours sincerely,"], a: 2, e: "When you know the person’s name in a formal email, close with “Yours sincerely,”." },
      { q: "The task says: include the date, the venue and the number of pupils. Your email has the date and the venue. What should you do?", o: ["Nothing, two out of three is enough.", "Add the number of pupils.", "Add a joke instead."], a: 1, e: "Every point in the task must be included. Missing one loses marks for content." }
    ] },
    { type: "fixit", title: "Make it formal", intro: "Each line is too informal for an email to an adult you do not know well. Rewrite it in a formal tone.", items: [
      { wrong: "Hey Mr Tan, wassup?", right: "Dear Mr Tan,", why: "Use a polite greeting. Slang like “wassup” is not suitable for a formal email." },
      { wrong: "Can u tell me if the pool is open on Sat?", right: "Could you please tell me whether the swimming pool is open on Saturday?", why: "Use full words (“you”, “Saturday”) and polite phrases like “Could you please”." },
      { wrong: "We wanna borrow 5 tables, ok?", right: "We would like to borrow five tables, if possible.", why: "“Wanna” is slang and “ok?” sounds demanding. “We would like to” is polite." },
      { wrong: "Sorry lah, I didn’t mean to break the window!!!", right: "I sincerely apologise for breaking the window. It was not my intention.", why: "Remove “lah” and the extra exclamation marks, and use a formal apology." },
      { wrong: "Pls reply asap.", right: "I look forward to your reply.", why: "Avoid short forms like “pls” and “asap”. Use a polite closing line." },
      { wrong: "Thx! Bye! From Priya", right: "Thank you for your time.<br><br>Yours sincerely,<br>Priya Nair", why: "Use a polite thank-you, a formal sign-off and your full name." }
    ] }
  ] }

] });
